    "expressionId": "attention.operation",
    "code": "class MultiHeadAttention(nn.Module):\n    def __init__(self, dim_in, dim_out, context_length,\n                 dropout, num_heads, qkv_bias=False):\n        super().__init__()\n        assert dim_out % num_heads == 0\n        self.dim_out = dim_out\n        self.num_heads = num_heads\n        self.head_dim = dim_out // num_heads\n\n        self.Wq = nn.Linear(dim_in, dim_out, bias=qkv_bias)\n        self.Wk = nn.Linear(dim_in, dim_out, bias=qkv_bias)\n        self.Wv = nn.Linear(dim_in, dim_out, bias=qkv_bias)\n        self.head_combined_projection = nn.Linear(dim_out, dim_out)\n        self.dropout = nn.Dropout(dropout)\n        self.register_buffer(\n            \"mask\", torch.triu(torch.ones(context_length, context_length), diagonal=1)\n        )\n\n    def forward(self, x):\n        batch, tokens, _ = x.shape\n        q = self.Wq(x)\n        k = self.Wk(x)\n        v = self.Wv(x)\n\n        q = q.view(batch, tokens, self.num_heads, self.head_dim).transpose(1, 2)\n        k = k.view(batch, tokens, self.num_heads, self.head_dim).transpose(1, 2)\n        v = v.view(batch, tokens, self.num_heads, self.head_dim).transpose(1, 2)\n\n        scores = q @ k.transpose(2, 3)\n        mask = self.mask.bool()[:tokens, :tokens]\n        scores.masked_fill_(mask, -torch.inf)\n        weights = torch.softmax(scores / self.head_dim ** 0.5, dim=-1)\n        weights = self.dropout(weights)\n\n        context = (weights @ v).transpose(1, 2).contiguous()\n        context = context.view(batch, tokens, self.dim_out)\n        return self.head_combined_projection(context)"
