    "expressionId": "model.operation",
    "code": "class GPT(nn.Module):\n    def __init__(self, config):\n        super().__init__()\n        self.config = config\n        self.tokens_embeddings = nn.Embedding(config[\"vocab_size\"], config[\"emb_dim\"])\n        self.positional_embeddings = nn.Embedding(config[\"context_length\"], config[\"emb_dim\"])\n        self.dropout = nn.Dropout(config[\"drop_rate\"])\n        self.transformer = nn.Sequential(\n            *(TransformerBlock(config) for _ in range(config[\"n_layers\"]))\n        )\n        self.final_norm = nn.LayerNorm(config[\"emb_dim\"])\n        # This teaching implementation keeps the output projection untied; GPT-2 ties it.\n        self.output_head = nn.Linear(config[\"emb_dim\"], config[\"vocab_size\"], bias=False)\n\n    def forward(self, idx):\n        _, seq_len = idx.shape\n        tok_emb = self.tokens_embeddings(idx)\n        positions = torch.arange(seq_len, device=idx.device)\n        pos_emb = self.positional_embeddings(positions)\n        x = self.dropout(tok_emb + pos_emb)\n        x = self.final_norm(self.transformer(x))\n        return self.output_head(x)\n\n\nGPT2_SMALL_STYLE_CONFIG = {\n    \"vocab_size\": 50257,\n    \"context_length\": 256,\n    \"emb_dim\": 768,\n    \"n_heads\": 12,\n    \"n_layers\": 12,\n    \"drop_rate\": 0.1,\n    \"qkv_bias\": False,\n}"
