    "expressionId": "generation.operation",
    "code": "def generate(model, idx, max_generated_tokens, temperature=1.0, top_k=None):\n    if temperature < 0:\n        raise ValueError(\"temperature must be zero (greedy) or positive\")\n\n    for _ in range(max_generated_tokens):\n        idx_context = idx[:, -model.config[\"context_length\"]:]\n        with torch.no_grad():\n            logits = model(idx_context)[:, -1, :]\n\n        if temperature == 0:\n            idx_next = torch.argmax(logits, dim=-1, keepdim=True)\n        else:\n            logits = logits / temperature\n            if top_k is not None:\n                if not 1 <= top_k <= logits.size(-1):\n                    raise ValueError(\"top_k must be between 1 and vocabulary size\")\n                top_logits, _ = torch.topk(logits, top_k)\n                cutoff = top_logits[:, -1, None]\n                logits = logits.masked_fill(logits < cutoff, -torch.inf)\n            probs = torch.softmax(logits, dim=-1)\n            idx_next = torch.multinomial(probs, num_samples=1)\n        idx = torch.cat((idx, idx_next), dim=1)\n    return idx\n\n\ndef encode(text):\n    return torch.tensor(tokenizer.encode(text)).unsqueeze(0)\n\n\ndef decode(tokens):\n    return tokenizer.decode(tokens.squeeze(0).tolist())"
